export type PeakLocale = "uk" | "en" | "de" | "pl" | "fr" | "es";
export const PEAK_LOCALES: PeakLocale[] = ["uk", "en", "de", "pl", "fr", "es"];

type PeakText = {
  name: string;
  country: string;
  title: string; // <title> і h1
  p: [string, string, string]; // про гору · що видно на моделі · кому подарувати
};

export type Peak = {
  slug: string;
  presetId: string;
  elev: number;
  areaKm: number;
  photo: string;
  lat: number;
  lon: number;
  t: Record<PeakLocale, PeakText>;
};

