export const PEAK_BY_SLUG: Record<string, Peak> = Object.fromEntries(PEAKS.map((p) => [p.slug, p]));

/** Сусідні вершини для перелінковки: спершу того ж «регіону» за індексом, по колу. */
export function relatedPeaks(slug: string, n = 6): Peak[] {
  const i = PEAKS.findIndex((p) => p.slug === slug);
  return Array.from({ length: Math.min(n, PEAKS.length - 1) }, (_, k) => PEAKS[(i + 1 + k) % PEAKS.length]);
}
